import { render, screen } from '@testing-library/react';
import React from 'react';
import ProgressTrackerFooter from './components/ProgressTrackerFooter/ProgressTrackerFooter';
import ProgressTrackerContentItem from './components/ProgressTrackerContent/components/ProgressTrackerContentItem/ProgressTrackerContentItem';
import ProgressTrackerContent from './components/ProgressTrackerContent/ProgressTrackerContent';
import { ProgressTracker } from '../..';

describe('ProgressTracker', () => {
  it('should render without crashing', () => {
    render(<ProgressTracker.Root orientation="vertical" size="small" currentStep={0} />);
    expect(screen.getByTestId('progress-tracker-container')).toBeInTheDocument();
  });

  it('should be render with children without crashing with default props', () => {
    const steps = ['A', 'B', 'C'];
    const stepWithError = 0;
    const stepCompleted = 1;
    render(
      <ProgressTracker.Root>
        <ProgressTracker.Header>
          {steps.map((step, index) => (
            <ProgressTracker.Step
              index={index}
              completed={stepCompleted === index}
              error={stepWithError === index}
              alertMessage={stepWithError === index ? 'Alert message' : null}
              key={step}
            >
              <ProgressTracker.StepLabel label={`Step ${step}`} detail="Detail" />
            </ProgressTracker.Step>
          ))}
        </ProgressTracker.Header>

        <ProgressTrackerContent>
          {steps.map((step, index) => (
            <ProgressTrackerContentItem index={index} key="item">
              {`Showing content ${step} on index ${index}`}
            </ProgressTrackerContentItem>
          ))}
        </ProgressTrackerContent>

        <ProgressTrackerFooter />
      </ProgressTracker.Root>
    );
  });
});
